    const AX=(R,n,k,e)=>{ const A=E.axis(R,n,k).concat(e||[]); A.sort((a,b)=>a-b); return A.filter((v,i)=>i===0||v-A[i-1]>.05); }; // 지형 축(가운데 촘촘) + 구멍 모서리 선
    const VIEW=(x,z,r0)=>{ const a=Math.atan2(z,x); return Math.abs(a-.87)<.6&&Math.hypot(x,z)<r0; }; // 눈높이·정면 카메라 쪽 부채꼴(가리지 않게 비움)

    // 서울 도심(축: +z=남, -z=북, x=동서): 남산 능선(기존 지형) 밖으로 바깥 지형 띠(±1.3 km → 4 km) · 북쪽 명동·을지로·종로 도심(고층 유리·석재 오피스), 그 너머 북악산·인왕산 · 남쪽 해방촌·이태원 저층 주택가와 용산공원(옛 미군기지, 남서) · 남쪽 약 2.4 km 한강(폭 약 1 km) · 강 건너 반포·강남, 멀리 관악산 — 배치·높이 개략(추정)
    const HH=(x,z)=>(Math.abs(x)<1290&&Math.abs(z)<1290)?TRN.h(x,z):TR.h(x,z);
